"""Compile authored ad directions. Does not modify the public catalogue or call generation APIs."""
from pathlib import Path
import json,re,unicodedata
ROOT=Path(__file__).resolve().parents[3];REC=Path(__file__).parent;WORK=ROOT.parent/'work/ads-440';WORK.mkdir(parents=True,exist_ok=True)
GROUPS=[('moda','Moda e vestuário',0,['ads-moda-masculina','ads-moda-feminina','ads-biquinis','ads-pijamas']),('alimentacao','Alimentação e bebidas',2,['ads-organicos','ads-barras','ads-cereal']),('casa','Casa e decoração',14,['ads-capachos']),('joias','Joias e acessórios',14,['ads-joias']),('juridico','Serviços jurídicos',14,['ads-advocacia']),('pets','Pets e cuidados animais',20,[]),('automotivo','Automotivo e mobilidade',20,[]),('turismo','Turismo e hospedagem',20,[]),('beleza','Beleza e autocuidado',20,[]),('servicos','Serviços residenciais',20,[]),('infantil','Infantil e maternidade',20,[])]
NATURAL=[
('Conversa com detalhe útil','Human-shot smartphone portrait, lived-in setting, genuine conversational gesture; one large subject, alternating a stable medium shot with meaningful physical actions.'),
('POV de decisão prática','First-person adult hands and concrete use; intentional near and far planes, real surfaces, gentle camera movement driven by hands, no floating graphics.'),
('Diário de uma escolha','Documentary micro-story with three connected everyday settings, candid adult posture, soft window light and tactile foreground objects.'),
('Bancada de demonstração','Adult presenter and real tabletop demonstration, clear oblique close-ups, believable proportions, carefully arranged tools, no clinical or performance results invented.'),
('Pergunta antes da compra','A visually attractive adult creator answers a practical question through action; large objects in frame, domestic window light, restrained handheld camera.'),
('Observação sem pose','Observational documentary framing; genuine physical preparation, people not posing at camera in every frame, subtle layered depth and motivated focus.'),
('Detalhe e contexto','Editorial creator footage alternating useful close details and honest wider context, tactile atmosphere, no extreme lens distortion.'),
('Rotina de mãos e objetos','Close adult hands interacting with objects, occasional human-height context, original foley implied through physical action, purposeful framing.'),
('Comparação sob a mesma luz','Honest side-by-side physical comparison with equivalent exposure and scale; only confirmed external features, clean legible object spacing.'),
('Do espaço para o produto','Natural walkthrough in an authorized-looking fictional setting; intentional foreground architecture, one stable perspective at a time, scale visible.'),
('Preparação em um único ambiente','Creator micro-documentary in one coherent everyday setting; dynamic framing through opening, arranging, using and explaining objects.'),
('Retrato com demonstração próxima','Human portrait balanced with detailed hands and product, shallow depth where useful, normal skin texture and relaxed adult expressions.'),
('Uma dúvida em quatro ações','A practical four-step visual argument, candid human presence, tactile materials, no stock posing, no floating objects, strong visual differentiation per frame.'),
('Mesa de escolha informada','Adult decision process at a table with thoughtfully arranged objects and genuine environmental details; calm credible smartphone realism.'),
('Trajeto e pausa de uso','A short lived-in journey linked by a real object, human-height camera and small perspective changes, believable transitions and natural light.'),
('Ritual sem encenação de resultado','A real-looking preparation ritual with clear object actions, natural skin and materials, no staged testimonials or before-after claims.'),
('Conversa de quem demonstra','Presenter footage with useful large cutaways; subtle foreground blur, soft daylight, varied shot distance, natural visible anatomy.'),
('A decisão vista pelas mãos','Hands drive the story through opening, checking, comparing and choosing; rich but natural tabletop textures, adult cast only unless the brief explicitly requires otherwise.'),
('Ambiente vivido, objeto em destaque','Human-shot creator documentary with useful real-looking environmental layers and a visually dominant product or service detail, no visual clutter.'),
('Demonstração com referência clara','Stable creator footage and oblique detail views, honest scale and lighting, a clear outcome of each physical gesture, no implied performance test.')]
ELAB=[
('Cenografia de revelação','Sophisticated practical reveal set with moving physical panels and occlusion; big subjects, tactile stage materials, attractive coherent light, zero flat template look.'),
('Editorial em duas profundidades','High-end editorial advertising photo with two distinct depth planes, asymmetrical composition, foreground material framing and confident negative space for editable typography.'),
('Cena construída por materiais','Luxury tactile scenography combining paper, fabric, mineral or acrylic appropriate to the brief; physical weight, soft contact shadows and believable human action.'),
('Match cut por forma real','Campaign storyboard organized around a concrete matching shape or gesture; large objects, precise composition, changing scene scale and convincing light continuity.'),
('Retrato e objeto em palco','Adult editorial portrait and dominant product/service object in a beautiful physical set; dimensional backdrop, motivated edge light, no plastic skin or empty stock staging.'),
('Percurso de câmera por camadas','Comfortable cinematic tracking through foreground occluders and layered practical scenery; meaningful reveal in each frame, no invented hidden product geometry.'),
('Teatro de papel e luz','Elegant physical paper theatre around a protected photographic subject; sculptural folds, lateral light and strong editorial composition, no cartoon flattening.'),
('Composição de galeria tátil','Gallery-like display with different physical support heights, rich surface texture, refined lighting and clear large-scale items; not small isolated floating products.'),
('Fotografia e painéis translúcidos','Premium photographic campaign with frosted acrylic/glass scenery and layered reflections; readable blank panel reserved for code typography, main subject unobstructed.'),
('Ritmo por gesto e objeto','A cinematic series linked by one real gesture or object, variations in camera distance, attractive detailed practical environments and human action.'),
('Sombras como cenário de campanha','Architectural soft shadows shape the backdrop, while the subject retains honest neutral color; sculptural composition, precise highlights and deep physical layering.'),
('Palco de módulos em movimento','A visually complex modular practical set built for a campaign; offset platforms, moving panels and real human interaction, no flat infographic or artificial product morphing.'),
('Janela editorial de aproximação','Physical framing devices and motivated optical close-up connect a wide scene with useful details; refined art direction, layered materials and careful negative space.'),
('Campanha com escala humana','An editorial architectural set with normal-size people and prominent real-looking objects, strong sense of depth and action, grounded proportions and no toy-like humans.'),
('Foley em composição escultórica','Objects and adult hands are arranged as a refined photographic choreography suitable for sound-driven edits; tactile macro, stable meaningful actions, cinematic light.'),
('Vitrine de informação dimensional','A sophisticated product/service campaign set with blank physical tabs, plaques or sheets for later exact editable text; large photographs, overlapping depth and tactile materials.'),
('Superfícies e reflexos controlados','A premium campaign using matte and reflective surfaces in carefully different planes; exact external product identity, natural human skin, coherent camera perspective.'),
('Um objeto liga ambientes','A physical object bridges clearly different campaign environments via match cuts; detailed scenography, believable interaction, wide-to-detail progression and attractive layered light.'),
('Imagem grande e tipografia editorial','Confident editorial campaign composition with a large photographic subject, tactile surrounding set and deliberate clear upper/side space for later code typography.'),
('Fechamento de marca com presença','A rich photographic campaign finale designed around a strong hero object or adult portrait, dimensional practical scenery, refined materials and warm/cool motivated light.')]
def slug(v):return re.sub('[^a-z0-9]+','-',unicodedata.normalize('NFKD',v).encode('ascii','ignore').decode().lower()).strip('-')
BASE='''Generate a beautifully art-directed advertising storyboard CONTACT SHEET. EXACTLY FOUR fully filled portrait photographs, arranged in a precise seamless 2 by 2 grid with equal halves. Whole sheet portrait 2:3; each panel portrait 2:3. NO gutters, NO panel borders, NO labels, NO numbers, NO written text, NO letters, NO watermarks, NO real brand logos. Typography, subtitles, real labels and CTA are composed later in editable code, never generated inside this image. Four genuinely DIFFERENT meaningful frames, not four repeated product poses. Dominant large subjects, attractive human-shot photographic realism, rich tactile environments, physically plausible depth and perspective, coherent light, soft-to-moderate contrast with restrained saturation, no gray haze, no waxy skin, no stock-photo posing and no cheap CGI. Preserve the SAME fictional product construction, variant/color and SAME recognizable fictional adult people across all four frames; realistic anatomy, skin, hands and body proportions. Do not copy the identity of real campaign celebrities or people. All products, properties, people, facts and situations are FICTIONAL CONCEPT EXAMPLES, not proof of results or a real testimonial. No fabricated numerical specifications or labels. Do not invent anatomical mechanisms, hidden product geometry or service results. Human actions must have a plausible visible consequence. For properties show one coherent fictional place, never surreal architecture; for animals use natural unscripted-looking safe behavior; for infant products prioritize responsible adults and safe tabletop demonstrations, no exposed child or dangerous use. For legal services use sober informative professional presentation, fictional documents without private data, no spectacle or fabricated case outcome. Refined, contemporary Brazilian advertising context; meaningful set dressing, recognizable normal material texture, useful details and consistent object scale. Product/people remain unobstructed by props. Leave modest clean space in at least the hero second panel for later editable campaign text, without making the subject tiny. Follow the following authored direction in Portuguese and the production-design notes exactly.\n'''
jobs=[];groups=[]
for group,label,natural_count,legacy in GROUPS:
 rows=[line.split(' | ') for line in (REC/'briefs'/f'{group}.txt').read_text().splitlines() if line.strip()]
 expected=40-sum(6 for _ in legacy);assert len(rows)==expected,(group,len(rows),expected)
 groups.append(dict(id='ads-'+group,name=label,newCount=len(rows),legacyFamilies=legacy,totalCount=40,naturalNewCount=natural_count))
 for index,(name,subniche,hook,beats,look,proof) in enumerate(rows):
  frames=beats.split(' → ');assert len(frames)==4,(group,name)
  natural=index<natural_count;art_index=index if natural else index-natural_count
  layout,design=(NATURAL if natural else ELAB)[art_index%20]
  framework='DBO' if index%2==0 else 'AIDA'
  cta={'juridico':'Leia o conteúdo informativo completo','turismo':'Consulte as opções e condições da reserva','servicos':'Conheça o serviço e as condições de atendimento','automotivo':'Consulte a aplicação ou o serviço confirmado','pets':'Confira os detalhes e cuidados desta opção','beleza':'Conheça a variante e suas informações','infantil':'Confira a indicação e os detalhes do produto'}.get(group,'Conheça as opções e os detalhes do produto')
  j=dict(id='ads26-'+group+'-'+slug(name),name=name,family='ads-'+group,familyName=label,subniche=subniche,creativeMode='natural_ugc' if natural else 'campaign_composite',framework=framework,hook=hook,beats=frames,look=look,proofNeed=proof,cta=cta,heroIndex=1 if group=='automotivo' and name=='O orçamento sai da sombra' else 2,layout=layout,design=design,targetDurationRange=[30,45])
  j['prompt']=(BASE if group=='infantil' else BASE.replace('for infant products prioritize responsible adults and safe tabletop demonstrations, no exposed child or dangerous use. ','')).replace('Leave modest clean space in at least the hero second panel','Leave modest clean space in at least one panel')+f"CONCEITO: {name}. NICHO: {label} / {subniche}. DIREÇÃO VISUAL: {look}.\n"+f"PRODUCTION DESIGN: {design}\n"+'\n'.join(f'PANEL {i+1} ({["TOP LEFT","TOP RIGHT","BOTTOM LEFT","BOTTOM RIGHT"][i]}): {b}.' for i,b in enumerate(frames))+f"\nCONSUMER QUESTION (meaning only, do not write): {hook}\nDo not depict as proven: {proof}. No text generated. Strong varied composition per state; four equal full portrait frames, exact 2x2 grid, no borders or padding."
  jobs.append(j)
assert len(jobs)==380 and len({j['id'] for j in jobs})==380
(REC/'concepts.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n');(REC/'groups.json').write_text(json.dumps(groups,ensure_ascii=False,indent=2)+'\n');(WORK/'jobs.json').write_text(json.dumps(jobs,ensure_ascii=False))
(WORK/'results').mkdir(exist_ok=True);print('380 new authored sequences, 140 existing-segment expansion + 240 new segments. 440 ads total with 60 preserved.')
